import {survivalBuildings,survivalRoomCatalog,survivalSiteObservation} from './survival-exploration.js';
import {minimapSites,minimapTerrain} from './campus-map.js';
const exploreEsc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function survivalExplorationPage(state,selected='arts',floor=''){
 const r=state.survivalRun,building=survivalBuildings[selected]?selected:'arts',rooms=Object.entries(survivalRoomCatalog).filter(([,d])=>d.building===building),floors=[...new Set(rooms.map(([,d])=>d.floor))],selectedFloor=floors.includes(floor)?floor:floors[0],here=survivalRoomCatalog[r.exploration?.here],ready=r.stage==='settlement';
 return `<section class="survival-exploration"><header><span class="shelter-kicker">돌아올 공간을 직접 찾기</span><h2>${ready?'어느 건물부터 살펴볼까':'아직은 도주 중'}</h2><p>${ready?'건물과 층을 골라 탐색 경로를 정하세요. 방의 실제 상태는 이동해서 내부를 확인해야 알 수 있어요.':'도주로를 두 번 통과하고 사태 3일차가 되면 실내 공간을 탐색할 수 있어요.'}</p><p class="explore-position">마지막으로 확인한 곳 · ${here?exploreEsc(here.name):'아직 없음'}</p></header><div class="shelter-map-scroll"><div class="shelter-campus-map" aria-label="거점 탐색용 캠퍼스 지도">${minimapTerrain()}${Object.entries(survivalBuildings).map(([id,name])=>{const [x,y,w,h]=minimapSites[id],known=Object.entries(survivalRoomCatalog).filter(([key,d])=>d.building===id&&r.scouted[key]).length;return `<button class="shelter-map-building ${id===building?'explore-selected':''}" data-action="survivalExploreBuilding" data-value="${id}" style="--map-x:${x}%;--map-y:${y}%;--map-w:${w}%;--map-h:${h}%" aria-pressed="${id===building}" aria-label="${name} 탐색 경로 · 확인한 공간 ${known}개"><strong>${name}</strong><small>${known?'확인 '+known+'곳':'내부 미확인'}</small></button>`;}).join('')}</div></div><p class="shelter-note">건물 선택은 경로 확인이며 소비가 없어요. 실제 이동·내부 확인은 아래 방을 선택할 때 여력 1을 사용해요. 게임용 배치도입니다.</p><article class="explore-room-panel"><div class="explore-room-heading"><h3>${survivalBuildings[building]} · ${selectedFloor}</h3><nav aria-label="탐색할 층">${floors.map(f=>`<button data-action="survivalExploreFloor" data-value="${f}" aria-pressed="${f===selectedFloor}">${f}</button>`).join('')}</nav></div><div class="explore-rooms">${rooms.filter(([,d])=>d.floor===selectedFloor).map(([id,d])=>{const observed=survivalSiteObservation(r,id),secured=r.secured[id],status=!observed?'내부 미확인':secured?'감염체 없음':observed.occupants>0?'감염체 점령':'재확인 필요';return `<article class="explore-room ${observed?secured?'room-empty':'room-occupied':'room-unknown'}" data-site="${id}"><span class="explore-state">${status}</span><h3>${exploreEsc(d.name)}</h3>${!observed?'<p>문 안의 상태와 안전도는 아직 몰라요.</p>':`<p>${exploreEsc(d.note)}</p><p>문 상태 ${observed.integrity}/100 · 복도 노출 ${observed.exposure===0?'낮음':observed.exposure===6?'보통':'높음'}</p><p>수용 ${d.capacity}명 · 시설 ${d.slots}칸 · 현재 예상 방어 ${Math.max(0,d.defense-observed.exposure-Math.floor((100-observed.integrity)/3))}</p>${observed.occupants>0?`<p class="explore-danger">내부에서 감염체 ${observed.occupants}마리를 확인했어요. 다른 방을 찾아도 돼요.</p>`:!secured?'<p>작전 중 물러난 곳이에요. 다시 확인한 뒤 사용하세요.</p>':''}`}${!observed||!observed.occupants&&!secured?`<button data-action="survivalScout" data-value="${id}" ${!ready||!!r.kit?.pending||r.actions<1?'disabled':''}>${observed?'다시 내부 확인':'이동해서 내부 확인'} · 여력 1</button>`:!secured?`<button data-action="survivalSecure" data-value="${id}" ${!ready||!!r.kit?.pending||r.actions<1?'disabled':''}>감염체 제압 · 전투 / 여력 1</button>`:`<button data-action="survivalClaim" data-value="${id}" ${!ready||!!r.kit?.pending||r.actions<1||r.resources.parts<d.cost||r.members.length>d.capacity?'disabled':''}>${r.members.length>d.capacity?'인원을 수용할 수 없음':'이곳을 거점으로 · 부품 '+d.cost+' / 여력 1'}</button>`}</article>`;}).join('')}</div></article></section>`;
}
